import org.jsoup.Connection;
import org.jsoup.helper.UrlBuilder;
import org.junit.Test;
import static org.junit.Assert.*;
import java.net.URL;

public class UrlBuilderTest {
    @Test
    public void UrlBuilderConstructorTest() throws Exception {
        URL inputUrl = new URL("http://localhost/test?param1=value1");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        assertEquals("Should set URL to input URL", inputUrl, urlBuilder.u);
        assertEquals("Should set query string to URL query", "param1=value1", urlBuilder.q.toString());
    }

    @Test
    public void buildWithNoRefOrQueryTest() throws Exception {
        URL inputUrl = new URL("http://localhost/test");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        assertEquals("Should return normalized URL", new URL("http://localhost/test"), urlBuilder.build());
    }

    @Test
    public void buildWithQueryTest() throws Exception {
        URL inputUrl = new URL("http://localhost/test?param1=value1");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        assertEquals("Should return normalized URL", new URL("http://localhost/test?param1=value1"), urlBuilder.build());
    }

    @Test
    public void buildWithQueryAndRefTest() throws Exception {
        URL inputUrl = new URL("http://localhost/test?param1=value1#ref");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        assertEquals("Should return normalized URL", new URL("http://localhost/test?param1=value1#ref"), urlBuilder.build());
    }

    @Test
    public void appendKeyValTest() throws Exception {
        URL inputUrl = new URL("http://localhost/test");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        Connection.KeyVal kv = Connection.KeyVal.create("param1", "value1");
        urlBuilder.appendKeyVal(kv);
        assertEquals("Should append key-val to query", "param1=value1", urlBuilder.q.toString());
    }

    @Test(expected = UnsupportedEncodingException.class)
    public void appendKeyValUnsupportedEncodingExceptionTest() throws Exception {
        URL inputUrl = new URL("http://localhost/test");
        UrlBuilder urlBuilder = new UrlBuilder(inputUrl);
        Connection.KeyVal kv = Connection.KeyVal.create("param1", "value\uFFFF");
        urlBuilder.appendKeyVal(kv);
    }

    @Test
    public void decodePartTest() throws Exception {
        String encoded = "param1%3Dvalue1";
        String decoded = UrlBuilder.decodePart(encoded);
        assertEquals("Should return decoded string", "param1=value1", decoded);
    }

    @Test(expected = RuntimeException.class)
    public void decodePartUnsupportedEncodingExceptionTest() throws Exception {
        String encoded = "param1%3Dvalue\uFFFF";
        UrlBuilder.decodePart(encoded);
    }

    @Test
    public void normalizeQueryTest() throws Exception {
        String q = "param1=value1";
        String normalized = UrlBuilder.normalizeQuery(q);
        assertEquals("Should return normalized string", "param1=value1", normalized);
    }

    @Test
    public void normalizeRefTest() throws Exception {
        String r = "reference";
        String normalized = UrlBuilder.normalizeRef(r);
        assertEquals("Should return normalized string", "reference", normalized);
    }
}
